# her 14 Nov ("대화하는게 너무 딱딱한데 좀 더 듣기 좋게 자연스럽게"): the Beginner stories rewritten as easy, natural talk
import sys, re
sys.argv = ['x']; sys.path.insert(0, '/tmp/claude-0/tts')
import storyaudio as S
src = open('/tmp/claude-0/lvl/levelstory.py').read()
NEW = {
 'hbr-B1': ('<p>Clara has just moved into a tall house full of music. She heads straight for the piano, but the Butler gets there first. “Not so fast,” he says. “Every pianist starts with the chair.”</p><p>“The chair?” asks Clara. “The chair,” says the Butler, and he shows her, one thing at a time. Sit on the front half of the stool. Feet flat on the floor. Back tall, shoulders soft. And the stool just high enough that your arms are level with the keys, like a table top.</p>',
            '<p>Nearly two hundred years ago, another girl named Clara, <b>Clara Wieck</b>, gave her first public concert at the Gewandhaus in Leipzig. She was nine.</p><p>She grew up to be one of the finest pianists of her day, <b>Clara Schumann</b>. Even she had to start at the beginning.</p>'),
 'hbr-P1': ('<p>Clara tries to count the keys. Somewhere after forty she loses track, starts again, and loses track again. “How many are there?” she asks.</p><p>“Eighty-eight,” says the Butler. “But don’t bother counting. Look at the black keys instead: twos and threes, all the way along. That’s how pianists find their way.”</p>',
            '<p><b>Mozart’s</b> piano had only about five octaves. The full eighty-eight keys came almost a hundred years later.</p><p>But the black keys already sat in their twos and threes. The pattern is older than the piano you see today.</p>'),
 'hbr-L1': ('<p>On the practice-room wall hangs an old board of bells, numbered one to five. When a bell rings, everyone in the house knows exactly who’s wanted.</p><p>“Your fingers have numbers too,” explains the Butler. “Your thumb is 1, on both hands.” Clara holds up her hands. “Then one hand is back to front!” she says. “Exactly,” says the Butler. “Put your palms together. 1 meets 1, and 5 meets 5, like a mirror. Going up the keys, the right hand plays 1 2 3 4 5, and the left hand plays 5 4 3 2 1.”</p>',
            '<p>Long ago, lots of keyboard players hardly used their thumbs at all. The thumb just dangled below the keys. Then, in 1753, <b>Carl Philipp Emanuel Bach</b>, one of Johann Sebastian Bach’s sons, wrote a famous book about playing the keyboard. In it he said that his father had made the thumb a proper working finger.</p><p>These days the thumb gets the best number of all. It’s number 1.</p>'),
 'hbr-P2': ('<p>Two important people share the lines in this house. The <b>Queen</b> rules the high floor. The <b>King</b> rules the low one.</p><p>Each of them has a sign at the start of their floor. “Mine is the treble clef,” says the Queen. “And mine is the bass clef,” says the King. “Don’t mix them up,” whispers the Butler. “They’re very particular.”</p>',
            '<p>About a thousand years ago, a monk named <b>Guido</b> wanted his singers to learn songs faster. So he drew lines, and put each note either on a line or in a space between.</p><p>Clefs began life as plain letters written at the start of a line: F and C first, then G a little later. Over the years, the letters curled into the signs you see today.</p>'),
 'hbr-T1': ('<p>In the hall stands a clock that has never once been late. Tick, tick, tick. Never faster, never slower.</p><p>“Music has a clock inside it too,” says the Butler. “We call it the <b>beat</b>.” “Where is it?” asks Clara. “Underneath,” says the Butler. “The beat always walks under the music, like a floor under a dance. The notes can run or wait. The beat just keeps going.”</p>',
            '<p>A man named <b>Maelzel</b> sold a little ticking machine to keep the beat: the <b>metronome</b>. A Dutchman named Winkel actually built it first, but Maelzel’s name went on the box. <b>Beethoven</b> was one of the first composers to write metronome numbers on his music.</p><p>The clock in the hall would have approved.</p>'),
 'hbr-T2': ('<p>Two notes meet in the hall. One is gone in a single tick. The other waits, and waits, for two.</p><p>“That slow one is called a <b>minim</b>,” says the Butler. “But minim sounds tiny,” says Clara. “It does,” says the Butler. “There’s a story in that.”</p>',
            '<p>Seven hundred years ago, the minim really was one of the shortest notes around. Its name comes from the Latin <i>minima</i>, the smallest.</p><p>Over the centuries, composers kept inventing shorter and shorter notes, and the old ones slowly grew longer. The name stayed put. Now the minim is one of the long ones.</p>'),
 'hbr-T2-s2': ('<p>The Butler draws a minim and adds a tiny dot just after it. “What does the dot do?” asks Clara. “It adds half the note again,” says the Butler. “A minim is two beats. Half of two is one. So with the dot, it lasts three.” Clara holds the note and counts: one, two, three. The dot was the three.</p><p>Then the clock strikes four, and Clara is still holding her next note. She pressed it only once. “That,” says the Butler, “is a <b>semibreve</b>. One note for the whole bar.”</p>',
            '<p><b>Semibreve</b> means half a breve, and <i>breve</i> means short. Once upon a time, the breve really was a short note.</p><p>Like the minim, it grew longer over the years. Today the breve is so long you’ll hardly ever see it.</p>'),
 'hbr-E1': ('<p>It’s Thursday, and the house is having its <b>music evening</b>. Clara plays her first piece with every note at full strength: <b><i>forte</i></b>, loud and strong.</p><p>The music marches round the room like a parade. The cups ring on their saucers, the Queen sits up very straight, and the King taps his foot. The Butler puts down the tray. “Splendid,” he says. “Now the same piece, <i>piano</i>.”</p>',
            None),
 'hbr-ear-beginner': ('<p>Someone is playing in the next room, and the door is shut. Clara presses her ear against it.</p><p>Is it high or low? Is it the same tune as before, or a new one? She can’t see the keys this time. She can only listen.</p>',
            '<p>When the playing stops, Clara opens the door. There sits the Butler at the old practice piano, one finger still resting on a key.</p><p>“High, then low,” says Clara. “And the same tune twice.” The Butler writes one word in his little book: <i>Correct</i>. Good pianists listen first. The ear shows the fingers the way.</p>'),
}
